function listPicks(): string[] {
  const picks = localStorage.getItem('picks');
  return picks ? JSON.parse(picks) : [];
}

function addPick(id: string): void {
  const picks = listPicks();
  if (!picks.includes(id)) {
    const newPicks = [...picks, id];
    localStorage.setItem('picks', JSON.stringify(newPicks));
  }
}

function removePick(id: string): void {
  const picks = listPicks();
  const newPicks = picks.filter(p => p !== id);
